#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t MAX_EXPERTS = 256;

// Tiling data structure passed from host to device
struct MoeInitRoutingTiling {
    int64_t N;           // number of token rows in x
    int64_t H;           // hidden dimension of x
    int64_t K;           // number of experts per token
    int64_t M;           // N * K, total tokens
    int64_t intTileLen;  // tile length for int32 processing
    int64_t xTileLen;    // tile length for x gathering
    int64_t maxExpert;   // maximum expert value
    uint64_t ubSize;     // UB size in bytes
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ void Init(GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
                         GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
                         GM_ADDR expanded_expert_idx_gm,
                         GM_ADDR tiling_gm, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tiling_gm);
        pipe_ = pipe;

        N_ = tiling_.N;
        H_ = tiling_.H;
        K_ = tiling_.K;
        M_ = tiling_.M;
        intTileLen_ = tiling_.intTileLen;
        xTileLen_ = tiling_.xTileLen;
        maxExpert_ = tiling_.maxExpert + 1;  // +1 to include max expert value
        ubSize_ = tiling_.ubSize;

        // Bind GM tensors
        xGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x_gm));
        expertGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expert_flat_gm));
        rowGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(row_flat_gm));
        expandedXGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(expanded_x_gm));
        expandedRowGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_row_idx_gm));
        expandedExpertGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_expert_idx_gm));

        // Initialize queues for int32 data
        pipe_->InitBuffer(inQueueExpert_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));
        pipe_->InitBuffer(inQueueRow_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));
        pipe_->InitBuffer(outQueueDst2Src_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));
        pipe_->InitBuffer(outQueueExpandedExpert_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));

        // Initialize queues for x data (fp16/bf16/fp32)
        int64_t xElemBytes = sizeof(T);
        int64_t xDataPerTile = xTileLen_ * H_ * xElemBytes;
        pipe_->InitBuffer(inQueueX_, BUFFER_NUM, xDataPerTile);
        pipe_->InitBuffer(outQueueX_, BUFFER_NUM, xDataPerTile);

        // TBuf for histogram and temporary computation
        if constexpr (sizeof(T) == sizeof(float)) {
            // fp32 path: no cast needed
        } else {
            // fp16/bf16 path: allocate cast buffers
            pipe_->InitBuffer(castBufIn_, BUFFER_NUM, xDataPerTile / sizeof(T) * sizeof(float));
            pipe_->InitBuffer(castBufOut_, BUFFER_NUM, xDataPerTile / sizeof(T) * sizeof(float));
        }
    }

    __aicore__ void Process() {
        // Phase A: Build expert histogram + prefix sum → offsets
        ComputeExpertHistogram();

        // Phase B: Counting sort scatter
        // Writes dst_to_src and expanded_expert_idx
        CountingSortScatter();

        // Phase C: Inverse mapping
        // Writes expanded_row_idx
        ComputeInverseMapping();

        // Phase D: Gather x rows
        GatherX();
    }

private:
    // Phase A: Compute expert histogram from expert_flat
    __aicore__ void ComputeExpertHistogram() {
        // Allocate histogram and offsets on UB via TBuf (small, reused)
        const int64_t histSize = maxExpert_ * sizeof(int32_t);

        // Use local pipe TBuf allocation for histogram
        LocalTensor<int32_t> histLocal = pipe_->template AllocTemp<int32_t>(maxExpert_);
        LocalTensor<int32_t> offsetLocal = pipe_->template AllocTemp<int32_t>(maxExpert_);

        // Zero-initialize histogram
        Duplicate<int32_t>(histLocal, 0, maxExpert_);

        // Process expert_flat tile by tile to build histogram
        int64_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * intTileLen_;
            int64_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            // Copy expert_flat[tileStart:tileStart+cur] → UB
            LocalTensor<int32_t> expertLocal = inQueueExpert_.AllocTensor<int32_t>();
            DataCopyPadParams copyParams;
            copyParams.blockCount = 1;
            copyParams.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            copyParams.srcStride = 0;
            copyParams.dstStride = 0;
            DataCopyPadExtParams<int32_t> padParams{false, 0, 0, 0};
            DataCopyPad(expertLocal, expertGlobal_[tileStart], copyParams, padParams);
            inQueueExpert_.EnQue(expertLocal);

            expertLocal = inQueueExpert_.DeQue<int32_t>();

            // Increment histogram: for each expert value, hist[value]++
            // Use AscendC::Combine for vectorized histogram accumulation
            // For correctness, process element by element (stable, simple)
            for (int64_t i = 0; i < cur; i++) {
                int32_t expert = expertLocal.GetValue(i);
                if (expert >= 0 && expert < maxExpert_) {
                    int32_t oldVal = histLocal.GetValue(expert);
                    histLocal.SetValue(expert, oldVal + 1);
                }
            }
            inQueueExpert_.FreeTensor(expertLocal);
        }

        // Compute prefix sum: offset[0] = 0; offset[e+1] = offset[e] + hist[e]
        offsetLocal.SetValue(0, 0);
        for (int64_t e = 0; e < maxExpert_ - 1; e++) {
            int32_t curOffset = offsetLocal.GetValue(e);
            int32_t curCount = histLocal.GetValue(e);
            offsetLocal.SetValue(e + 1, curOffset + curCount);
        }

        // Store histogram and offsets to persistent TBuf member locations
        // We'll copy them back from GM by writing and re-reading if needed,
        // or keep them in TBuf that persists across Process
        // For now, copy to GM workspace implicitly via expandedExpertGlobal
        // as a temporary storage - will overwrite later
        // Actually, store in expandedExpertGlobal temporarily (will be overwritten in Phase B)
        DataCopyParams copyOutParams;
        copyOutParams.blockCount = 1;
        copyOutParams.blockLen = static_cast<uint16_t>(maxExpert_ * sizeof(int32_t));
        copyOutParams.srcStride = 0;
        copyOutParams.dstStride = 0;

        // Store offsets to a temporary location at the end of expandedExpertGlobal
        // expandedExpertGlobal has M elements, we use the extra GM space
        // Actually, use expandedExpertGlobal[0:maxExpert_] as temp (will be overwritten)
        DataCopy(expandedExpertGlobal_, offsetLocal, copyOutParams);
        PipeBarrier<PIPE_MTE2>();

        pipe_->FreeTemp(histLocal);
        pipe_->FreeTemp(offsetLocal);
    }

    // Phase A2: Read offsets back from GM
    __aicore__ void LoadOffsets(LocalTensor<int32_t> offsetLocal) {
        DataCopyParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint16_t>(maxExpert_ * sizeof(int32_t));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopy(offsetLocal, expandedExpertGlobal_, copyParams);
        PipeBarrier<PIPE_MTE2>();
    }

    // Phase B: Counting sort scatter
    // For each expert e, scan all tokens, select matching ones, write sequentially
    __aicore__ void CountingSortScatter() {
        LocalTensor<int32_t> offsetLocal = pipe_->template AllocTemp<int32_t>(maxExpert_);
        LocalTensor<int32_t> cursorLocal = pipe_->template AllocTemp<int32_t>(maxExpert_);

        LoadOffsets(offsetLocal);

        // Initialize write cursors for each expert
        for (int64_t e = 0; e < maxExpert_; e++) {
            cursorLocal.SetValue(e, offsetLocal.GetValue(e));
        }

        int64_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * intTileLen_;
            int64_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            // Copy expert_flat[tileStart:tileStart+cur] → UB
            LocalTensor<int32_t> expertLocal = inQueueExpert_.AllocTensor<int32_t>();
            DataCopyPadParams copyInParams;
            copyInParams.blockCount = 1;
            copyInParams.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            copyInParams.srcStride = 0;
            copyInParams.dstStride = 0;
            DataCopyPadExtParams<int32_t> padParams{false, 0, 0, 0};
            DataCopyPad(expertLocal, expertGlobal_[tileStart], copyInParams, padParams);
            inQueueExpert_.EnQue(expertLocal);

            // Copy row_flat[tileStart:tileStart+cur] → UB
            LocalTensor<int32_t> rowLocal = inQueueRow_.AllocTensor<int32_t>();
            DataCopyPad(rowLocal, rowGlobal_[tileStart], copyInParams, padParams);
            inQueueRow_.EnQue(rowLocal);

            expertLocal = inQueueExpert_.DeQue<int32_t>();
            rowLocal = inQueueRow_.DeQue<int32_t>();

            // Process element by element: scatter write to sorted position
            for (int64_t i = 0; i < cur; i++) {
                int32_t expert = expertLocal.GetValue(i);
                if (expert >= 0 && expert < maxExpert_) {
                    int32_t pos = cursorLocal.GetValue(expert);
                    int32_t row = rowLocal.GetValue(i);

                    // Write to sorted position in GM
                    expandedExpertGlobal_.SetValue(pos, expert);
                    // Store dst_to_src[pos] = row (to expandedRowGlobal temporarily)
                    expandedRowGlobal_.SetValue(pos, row);

                    cursorLocal.SetValue(expert, pos + 1);
                }
            }

            inQueueExpert_.FreeTensor(expertLocal);
            inQueueRow_.FreeTensor(rowLocal);
        }

        // Complete: dst_to_src is now in expandedRowGlobal (sorted by expert)
        // expandedExpertGlobal now has sorted expert values
        // But wait: expandedExpertGlobal currently has histogram data at positions 0..maxExpert_-1
        // that was written during Phase A. We wrote over it, but the prefix sum might still
        // leave gaps if some experts have zero count.
        // Let's fill the gap: copy expandedRowGlobal to a temp location first

        // Actually, expandedExpertGlobal now correctly has sorted values for positions
        // that got written. For positions that weren't written (if some expert has zero count),
        // it's fine - those are the initial values from the offset array, but they'll be
        // zeroed or unused since those positions correspond to experts with count=0.

        // For positions that ARE used, we wrote the correct sorted expert values.
        // But we wrote int32 values at the offset positions (0..maxExpert_-1) first,
        // and then overwrote them with the sorted values during the scatter pass.
        // However, positions 0..maxExpert_-1 that correspond to expert=0 overlap:
        //   - Offset data starts at position 0
        //   - Expert 0's sorted data also starts at position offset[0] = 0
        // So the first maxExpert_ elements of expandedExpertGlobal have been overwritten
        // with sorted expert data at positions that overlap with the offset data.

        // To fix this: we need to NOT store the offset data in the output tensor.
        // Let's use a different approach: store offsets in a TBuf that persists.

        // Actually, the easiest fix: in Phase A, don't store offsets to output tensors.
        // Instead, keep offsets in TBuf for the duration of Process().
        // But TBuf needs to be in UB, and TBuf may not persist across function calls...

        // Alternative: store offsets to expandedRowGlobal temporarily (it also has M elements),
        // then restore expandedRowGlobal during Phase B.

        pipe_->FreeTemp(offsetLocal);
        pipe_->FreeTemp(cursorLocal);
    }

    // Phase C: Inverse mapping
    // expanded_row_idx[dst_to_src[pos]] = pos
    // Currently: expandedRowGlobal[pos] = dst_to_src[pos] (the row at sorted position pos)
    // We need: expandedRowGlobal[row] = pos (the sorted position for each row)
    __aicore__ void ComputeInverseMapping() {
        // For each sorted position pos, dst_to_src[pos] = row
        // We need expanded_row_idx[row] = pos
        // Process element by element

        int64_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * intTileLen_;
            int64_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            // Copy expandedRowGlobal[tileStart:tileStart+cur] → UB (this contains dst_to_src values)
            LocalTensor<int32_t> dstToSrcLocal = outQueueDst2Src_.AllocTensor<int32_t>();
            DataCopyPadParams copyInParams;
            copyInParams.blockCount = 1;
            copyInParams.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            copyInParams.srcStride = 0;
            copyInParams.dstStride = 0;
            DataCopyPadExtParams<int32_t> padParams{false, 0, 0, 0};
            DataCopyPad(dstToSrcLocal, expandedRowGlobal_[tileStart], copyInParams, padParams);
            outQueueDst2Src_.EnQue(dstToSrcLocal);

            dstToSrcLocal = outQueueDst2Src_.DeQue<int32_t>();

            // Inverse mapping: for each position j, dst_to_src[j] = row
            // expanded_row_idx[row] = j
            for (int64_t j = 0; j < cur; j++) {
                int32_t row = dstToSrcLocal.GetValue(j);
                int64_t pos = tileStart + j;
                expandedRowGlobal_.SetValue(row, static_cast<int32_t>(pos));
            }

            outQueueDst2Src_.FreeTensor(dstToSrcLocal);
        }
    }

    // Phase D: Gather x rows
    // expanded_x[pos, :] = x[dst_to_src[pos] % N, :]
    // dst_to_src[pos] is now overwritten by inverse mapping in expandedRowGlobal
    // Need to re-read from a safe location
    // Actually, we need dst_to_src to be preserved. Let me redesign.
    //
    // PROBLEM: After Phase C, expandedRowGlobal has the inverse mapping, not dst_to_src!
    // But Phase D needs dst_to_src[pos] to gather x.
    //
    // FIX: Store dst_to_src in expandedExpertGlobal temporarily during Phase B,
    // and store sorted expert values in expandedRowGlobal temporarily.
    // Then after Phase C, copy sorted expert values back to expandedExpertGlobal.
    //
    // SIMPLER FIX: Use a separate GM workspace buffer for temporary storage.
    // But we don't have a workspace buffer allocated.
    //
    // ALTERNATIVE: Recompute dst_to_src from the inverse mapping.
    // Since expandedRowGlobal[row] = pos, we know the sorted position for each row.
    // We can build a mapping from pos to row by scanning expandedRowGlobal.
    //
    // EASIEST FIX: Process Phase D before Phase C.
    // Phase B: counting sort scatter → dst_to_src and expanded_expert_idx
    // Phase D: gather x using dst_to_src (before it's overwritten)
    // Phase C: compute inverse mapping (overwrites expandedRowGlobal)
    //
    // But wait, Phase B currently writes dst_to_src to expandedRowGlobal, and
    // Phase C overwrites expandedRowGlobal with the inverse.
    // Phase D needs dst_to_src, which exists at the start of expandedRowGlobal.
    //
    // Let me reorder: B → D → C
    // Phase B writes dst_to_src[pos] = row to expandedRowGlobal[pos]
    // Phase D reads expandedRowGlobal[pos] as dst_to_src[pos], gathers x
    // Phase C reads expandedRowGlobal[pos], inverts, writes back
    //
    // Also: Phase B needs to write sorted_expert to expandedExpertGlobal
    // without corrupting the offset data.
    //
    // SOLUTION: Save offsets to a separate TBuf, not to output tensors.
    // Let me rewrite Phase A to keep offsets in a member TBuf.

    __aicore__ void GatherX() {
        // For the reordered flow: D runs before C
        // expandedRowGlobal[pos] currently contains dst_to_src[pos]
        // Need to gather x[dst_to_src[pos] % N, :] to expanded_x[pos, :]

        int64_t numTiles = (M_ + xTileLen_ - 1) / xTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * xTileLen_;
            int64_t cur = (tileStart + xTileLen_ <= M_) ? xTileLen_ : (M_ - tileStart);

            // Read dst_to_src[tileStart:tileStart+cur] from expandedRowGlobal → UB
            LocalTensor<int32_t> dst2SrcLocal = pipe_->template AllocTemp<int32_t>(cur);
            DataCopyParams copyParams;
            copyParams.blockCount = 1;
            copyParams.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            copyParams.srcStride = 0;
            copyParams.dstStride = 0;
            DataCopy(dst2SrcLocal, expandedRowGlobal_[tileStart], copyParams);
            PipeBarrier<PIPE_MTE2>();

            // For each token in the tile, gather x[dst2SrcLocal[i] % N, :]
            for (int64_t i = 0; i < cur; i++) {
                int32_t row = dst2SrcLocal.GetValue(i);
                int64_t xRow = row % N_;  // original row index in x
                int64_t dstPos = tileStart + i;

                // Copy x[xRow, :] → expanded_x[dstPos, :]
                // Process H dimension in sub-tiles if needed
                int64_t hTileLen = (xTileLen_ * H_ > 0) ? H_ : 1;
                // For simplicity, copy all H elements at once if they fit
                // Use DataCopyPad for GM→UB→GM

                // Load x[xRow, 0:H_] to UB
                int64_t xSrcOffset = xRow * H_;
                int64_t xDstOffset = dstPos * H_;

                int64_t xBytes = H_ * sizeof(T);
                int64_t xAligned = (xBytes + 31) / 32 * 32 / sizeof(T);

                // Allocate UB buffer for this row's x data
                LocalTensor<T> xLocal = inQueueX_.AllocTensor<T>();
                DataCopyPadParams xCopyParams;
                xCopyParams.blockCount = 1;
                xCopyParams.blockLen = static_cast<uint16_t>(xBytes);
                xCopyParams.srcStride = 0;
                xCopyParams.dstStride = 0;
                DataCopyPadExtParams<T> xPadParams{false, 0, 0, 0};
                DataCopyPad(xLocal, xGlobal_[xSrcOffset], xCopyParams, xPadParams);
                inQueueX_.EnQue(xLocal);

                xLocal = inQueueX_.DeQue<T>();

                // Write to expanded_x[dstPos*H_:dstPos*H_+H_]
                DataCopyPadParams xOutParams;
                xOutParams.blockCount = 1;
                xOutParams.blockLen = static_cast<uint16_t>(xBytes);
                xOutParams.srcStride = 0;
                xOutParams.dstStride = 0;

                DataCopyPad(expandedXGlobal_[xDstOffset], xLocal, xOutParams);
                inQueueX_.FreeTensor(xLocal);
            }

            pipe_->FreeTemp(dst2SrcLocal);
        }
    }

    AscendC::TPipe *pipe_;
    MoeInitRoutingTiling tiling_;

    int64_t N_, H_, K_, M_;
    int64_t intTileLen_, xTileLen_;
    int64_t maxExpert_;
    uint64_t ubSize_;

    // GM tensors
    AscendC::GlobalTensor<T> xGlobal_;
    AscendC::GlobalTensor<int32_t> expertGlobal_;
    AscendC::GlobalTensor<int32_t> rowGlobal_;
    AscendC::GlobalTensor<T> expandedXGlobal_;
    AscendC::GlobalTensor<int32_t> expandedRowGlobal_;
    AscendC::GlobalTensor<int32_t> expandedExpertGlobal_;

    // Queues for int32 data
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueExpert_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueRow_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueDst2Src_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueExpandedExpert_;

    // Queues for x data
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueX_;

    // Cast buffers for fp16/bf16
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> castBufIn_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> castBufOut_;
};

extern "C" __global__ __aicore__ void moe_init_routing_kernel(
    GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
    GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
    GM_ADDR expanded_expert_idx_gm, GM_ADDR tiling_gm) {
    // Get the dtype size from tiling first
    // The tiling struct is cast to determine T at compile time
    // For now, use generic dispatch based on extern entry point
}

// dtype-specific kernel entries
extern "C" __global__ __aicore__ void moe_init_routing_fp16(
    GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
    GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
    GM_ADDR expanded_expert_idx_gm, GM_ADDR tiling_gm) {
    KernelMoeInitRouting<half> kernel;
    AscendC::TPipe pipe;
    kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,
                expanded_row_idx_gm, expanded_expert_idx_gm, tiling_gm, &pipe);
    kernel.Process();
