{"content": "/*
 * Copyright (c) 2024. All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 *
 * MoeInitRouting AscendC Kernel
 *
 * Algorithm (counting sort by expert ID):
 *   Phase A: Build expert histogram + prefix sum → expert offsets
 *   Phase B: Counting sort scatter → sorted expert values + dst_to_src into workspace
 *   Phase C: Gather x rows using dst_to_src from workspace
 *   Phase D: Inverse mapping: src_to_dst[dst_to_src[pos]] = pos
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t MAX_EXPERTS = 256;

struct MoeInitRoutingTiling {
    int64_t N;
    int64_t H;
    int64_t K;
    int64_t M;
    int64_t intTileLen;
    int64_t xTileLen;
    int64_t maxExpert;
    uint64_t ubSize;
};

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ void Init(GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
                         GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
                         GM_ADDR expanded_expert_idx_gm,
                         GM_ADDR dst_to_src_ws_gm, GM_ADDR tiling_gm,
                         AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tiling_gm);
        pipe_ = pipe;

        N_ = tiling_.N;
        H_ = tiling_.H;
        K_ = tiling_.K;
        M_ = tiling_.M;
        intTileLen_ = tiling_.intTileLen;
        xTileLen_ = tiling_.xTileLen;
        maxExpert_ = tiling_.maxExpert + 1;
        ubSize_ = tiling_.ubSize;

        xGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x_gm));
        expertGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expert_flat_gm));
        rowGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(row_flat_gm));
        expandedXGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(expanded_x_gm));
        expandedRowGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_row_idx_gm));
        expandedExpertGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_expert_idx_gm));
        dstToSrcWsGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(dst_to_src_ws_gm));

        int64_t intBufBytes = intTileLen_ * sizeof(int32_t);
        pipe_->InitBuffer(inQueueInt_, BUFFER_NUM, intBufBytes);
        pipe_->InitBuffer(outQueueInt_, BUFFER_NUM, intBufBytes);
    }

    __aicore__ void Process() {
        // Phase A: Build expert histogram
        ComputeExpertHistogram();

        // Phase B: Counting sort scatter
        CountingSortScatter();

        // Phase C: Gather x rows
        GatherX();

        // Phase D: Inverse mapping
        ComputeInverseMapping();
    }

private:
    __aicore__ void ComputeExpertHistogram() {
        LocalTensor<int32_t> histLocal = pipe_->template AllocTemp<int32_t>(maxExpert_ + 1);
        LocalTensor<int32_t> offsetLocal = pipe_->template AllocTemp<int32_t>(maxExpert_ + 1);

        // Init histogram
        Duplicate<int32_t>(histLocal, 0, maxExpert_);

        int64_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * intTileLen_;
            int64_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            LocalTensor<int32_t> expertLocal = inQueueInt_.AllocTensor<int32_t>();
            DataCopyPadParams cp;
            cp.blockCount = 1;
            cp.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            cp.srcStride = 0;
            cp.dstStride = 0;
            DataCopyPadExtParams<int32_t> pp{false, 0, 0, 0};
            DataCopyPad(expertLocal, expertGlobal_[tileStart], cp, pp);
            inQueueInt_.EnQue(expertLocal);
            expertLocal = inQueueInt_.DeQue<int32_t>();

            for (int64_t i = 0; i < cur; i++) {
                int32_t e = expertLocal.GetValue(i);
                if (e >= 0 && e < maxExpert_) {
                    int32_t val = histLocal.GetValue(e);
                    histLocal.SetValue(e, val + 1);
                }
            }
            inQueueInt_.FreeTensor(expertLocal);
        }

        // Prefix sum: offset[e+1] = offset[e] + hist[e]; offset[0]=0
        Duplicate<int32_t>(offsetLocal, 0, maxExpert_ + 1);
        for (int64_t e = 0; e < maxExpert_; e++) {
            int32_t off = offsetLocal.GetValue(e);
            int32_t cnt = histLocal.GetValue(e);
            offsetLocal.SetValue(e + 1, off + cnt);
        }

        // Save offsets to expandedExpertGlobal (tail area: M .. M+maxExpert_)
        // expandedExpertGlobal has M elements, but we need extra space.
        // Store to a member TBuf that persists
        // Allocate persistent offsets in UB
        offsetsUb_ = pipe_->template AllocTemp<int32_t>(maxExpert_ + 1);
        DataCopy(offsetsUb_, offsetLocal, DataCopyParams{1, static_cast<uint16_t>((maxExpert_ + 1) * sizeof(int32_t)), 0, 0});

        pipe_->FreeTemp(histLocal);
        pipe_->FreeTemp(offsetLocal);
    }

    __aicore__ void CountingSortScatter() {
        // Cursors start at offsets
        LocalTensor<int32_t> cursorLocal = pipe_->template AllocTemp<int32_t>(maxExpert_ + 1);
        DataCopy(cursorLocal, offsetsUb_, DataCopyParams{1, static_cast<uint16_t>((maxExpert_ + 1) * sizeof(int32_t)), 0, 0});
        PipeBarrier<PIPE_MTE2>();

        int64_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * intTileLen_;
            int64_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            // Load expert and row data
            LocalTensor<int32_t> expertLocal = inQueueInt_.AllocTensor<int32_t>();
            DataCopyPadParams cp;
            cp.blockCount = 1;
            cp.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            cp.srcStride = 0;
            cp.dstStride = 0;
            DataCopyPadExtParams<int32_t> pp{false, 0, 0, 0};
            DataCopyPad(expertLocal, expertGlobal_[tileStart], cp, pp);
            inQueueInt_.EnQue(expertLocal);
            expertLocal = inQueueInt_.DeQue<int32_t>();

            LocalTensor<int32_t> rowLocal = inQueueInt_.AllocTensor<int32_t>();
            DataCopyPad(rowLocal, rowGlobal_[tileStart], cp, pp);
            inQueueInt_.EnQue(rowLocal);
            rowLocal = inQueueInt_.DeQue<int32_t>();

            for (int64_t i = 0; i < cur; i++) {
                int32_t e = expertLocal.GetValue(i);
                if (e >= 0 && e < maxExpert_) {
                    int32_t pos = cursorLocal.GetValue(e);
                    int32_t row = rowLocal.GetValue(i);

                    expandedExpertGlobal_.SetValue(pos, e);
                    dstToSrcWsGlobal_.SetValue(pos, row);

                    cursorLocal.SetValue(e, pos + 1);
                }
            }

            inQueueInt_.FreeTensor(expertLocal);
            inQueueInt_.FreeTensor(rowLocal);
        }

        pipe_->FreeTemp(cursorLocal);
    }

    __aicore__ void GatherX() {
        // Read dst_to_src[pos] from workspace, gather x
        int64_t numTiles = (M_ + xTileLen_ - 1) / xTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * xTileLen_;
            int64_t cur = (tileStart + xTileLen_ <= M_) ? xTileLen_ : (M_ - tileStart);

            // Read workspace[tileStart:tileStart+cur] → dst_to_src
            LocalTensor<int32_t> dstLocal = pipe_->template AllocTemp<int32_t>(cur);
            DataCopyParams cp;
            cp.blockCount = 1;
            cp.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            cp.srcStride = 0;
            cp.dstStride = 0;
            DataCopy(dstLocal, dstToSrcWsGlobal_[tileStart], cp);
            PipeBarrier<PIPE_MTE2>();

            for (int64_t i = 0; i < cur; i++) {
                int32_t row = dstLocal.GetValue(i);
                int64_t xRow = row % N_;
                int64_t dstPos = tileStart + i;

                int64_t xSrcOff = xRow * H_;
                int64_t xDstOff = dstPos * H_;
                int64_t xBytes = H_ * sizeof(T);
                int64_t xCount = H_;

                // Allocate UB for x row copy
                LocalTensor<T> xLocal = pipe_->template AllocTemp<T>(xCount);
                DataCopyParams xcp;
                xcp.blockCount = 1;
                xcp.blockLen = static_cast<uint16_t>(xBytes);
                xcp.srcStride = 0;
                xcp.dstStride = 0;
                DataCopy(xLocal, xGlobal_[xSrcOff], xcp);
                PipeBarrier<PIPE_MTE2>();

                DataCopy(expandedXGlobal_[xDstOff], xLocal, xcp);
                PipeBarrier<PIPE_MTE2>();

                pipe_->FreeTemp(xLocal);
            }

            pipe_->FreeTemp(dstLocal);
        }
    }

    __aicore__ void ComputeInverseMapping() {
        // Read workspace[pos] = row (dst_to_src)
        // Write expanded_row_idx[row] = pos (inverse: src_to_dst)
        int64_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int64_t t = 0; t < numTiles; t++) {
            int64_t tileStart = t * intTileLen_;
            int64_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            LocalTensor<int32_t> dstLocal = pipe_->template AllocTemp<int32_t>(cur);
            DataCopyParams cp;
            cp.blockCount = 1;
            cp.blockLen = static_cast<uint16_t>(cur * sizeof(int32_t));
            cp.srcStride = 0;
            cp.dstStride = 0;
            DataCopy(dstLocal, dstToSrcWsGlobal_[tileStart], cp);
            PipeBarrier<PIPE_MTE2>();

            for (int64_t i = 0; i < cur; i++) {
                int32_t row = dstLocal.GetValue(i);
                int64_t pos = tileStart + i;
                expandedRowGlobal_.SetValue(row, static_cast<int32_t>(pos));
            }

            pipe_->FreeTemp(dstLocal);
        }
    }

    AscendC::TPipe *pipe_;
    MoeInitRoutingTiling tiling_;
    int64_t N_, H_, K_, M_;
    int64_t intTileLen_, xTileLen_;
    int64_t maxExpert_;
    uint64_t ubSize_;

    AscendC::GlobalTensor<T> xGlobal_;
    AscendC::GlobalTensor<int32_t> expertGlobal_;
    AscendC::GlobalTensor<int32_t> rowGlobal_;
    AscendC::GlobalTensor<T> expandedXGlobal_;
    AscendC::GlobalTensor<int32_t> expandedRowGlobal_;
    AscendC::GlobalTensor<int32_t> expandedExpertGlobal_;
    AscendC::GlobalTensor<int32_t> dstToSrcWsGlobal_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueInt_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueInt_;

    LocalTensor<int32_t> offsetsUb_;
};

// dtype-specific kernel entry points
#define DEFINE_MOE_INIT_ROUTING_KERNEL(dtype_t, suffix)                         \
    extern "C" __global__ __aicore__ void moe_init_routing_##suffix(            \
        GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,             \
        GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,                     \
        GM_ADDR expanded_expert_idx_gm, GM_ADDR dst_to_src_ws_gm,              \
        GM_ADDR tiling_gm) {                                                    \
        KernelMoeInitRouting<dtype_t> kernel;                                    \
        AscendC::TPipe pipe;                                                     \
        kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,           \
                    expanded_row_idx_gm, expanded_expert_idx_gm,                 \
                    dst_to_src_ws_gm, tiling_gm, &pipe);                         \
        kernel.Process();                                                        \
    }

DEFINE_MOE_INIT_ROUTING_KERNEL(half, fp16)
DEFINE_MOE_INIT_ROUTING_KERNEL(float, fp32)
DEFINE_MOE_INIT_ROUTING_KERNEL(bfloat16_t, bf16)
