#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_moe_init_routing_fp16.h"
#include "aclrtlaunch_moe_init_routing_fp32.h"
#include "aclrtlaunch_moe_init_routing_bf16.h"

namespace ascend_kernel {

struct MoeInitRoutingTiling {
    int64_t N;
    int64_t H;
    int64_t K;
    int64_t M;
    int64_t intTileLen;
    int64_t xTileLen;
    int64_t maxExpert;
    uint64_t ubSize;
};

static constexpr int32_t MAX_EXPERTS = 256;

at::Tensor moe_init_routing(
    const at::Tensor &x,
    const at::Tensor &row_idx,
    const at::Tensor &expert_idx,
    int64_t active_num) {

    // Validate inputs
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(expert_idx.dim() == 2, "expert_idx must be 2D");
    TORCH_CHECK(row_idx.dim() == 2, "row_idx must be 2D");
    TORCH_CHECK(row_idx.sizes() == expert_idx.sizes(),
                "row_idx and expert_idx must have same shape");
    TORCH_CHECK(x.dtype() == at::kFloat || x.dtype() == at::kHalf ||
                x.dtype() == at::kBFloat16,
                "x dtype must be float32, float16, or bfloat16");
    TORCH_CHECK(expert_idx.dtype() == at::kInt, "expert_idx must be int32");
    TORCH_CHECK(row_idx.dtype() == at::kInt, "row_idx must be int32");

    int64_t N = x.size(0);
    int64_t H = x.size(1);
    int64_t K = expert_idx.size(1);
    int64_t M = N * K;

    // Flatten expert_idx and row_idx
    auto expert_flat = expert_idx.contiguous().view(-1);
    auto row_flat = row_idx.contiguous().view(-1);

    // Allocate output tensors
    auto expanded_x = at::empty({M, H}, x.options());
    auto expanded_row_idx = at::empty({M}, at::dtype(at::kInt).device(x.device()));
    auto expanded_expert_idx = at::empty({M}, at::dtype(at::kInt).device(x.device()));

    // Allocate workspace for temporary dst_to_src storage
    auto dst_to_src_ws = at::empty({M}, at::dtype(at::kInt).device(x.device()));

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Compute tile lengths based on UB capacity
    // UB budget: leave ~4KB for histogram (MAX_EXPERTS * 4 * 2 ≈ 2KB)
    // and ~2KB for misc, so ~6KB overhead
    uint64_t ubOverhead = MAX_EXPERTS * sizeof(int32_t) * 3 + 4096;
    uint64_t usableUb = ubSize > ubOverhead ? ubSize - ubOverhead : ubSize / 2;

    // int processing: each tile uses BUFFER_NUM=2 * tileLen * sizeof(int32_t) * 2 (expert+row)
    // BUFFER_NUM copies of both expert and row
    int64_t intTileLen = static_cast<int64_t>(usableUb / (BUFFER_NUM * 2 * sizeof(int32_t)));
    // Align to 32
    intTileLen = (intTileLen / 32) * 32;
    if (intTileLen < 64) intTileLen = 64;
    if (intTileLen > 2048) intTileLen = 2048;

    // x gathering: each tile needs BUFFER_NUM * tileLen * H * sizeof(T)
    // plus a read buffer for dst_to_src
    int64_t xTileLen = 1;
    if (H > 0) {
        int64_t xs = static_cast<int64_t>(sizeof(float));  // worst case
        xTileLen = static_cast<int64_t>(usableUb / (BUFFER_NUM * H * xs + intTileLen * sizeof(int32_t)));
        if (xTileLen < 1) xTileLen = 1;
        if (xTileLen > 64) xTileLen = 64;
    }

    // Find max expert value (scan expert_flat for max)
    // Use CPU-side scan since it's fast
    int64_t maxExpert = 0;
    auto expert_acc = expert_flat.accessor<int32_t, 1>();
    for (int64_t i = 0; i < M; i++) {
        int32_t val = expert_acc[i];
        if (val > maxExpert) maxExpert = val;
    }
    if (maxExpert >= MAX_EXPERTS) {
        maxExpert = MAX_EXPERTS - 1;
    }

    // Fill tiling data
    MoeInitRoutingTiling tiling;
    tiling.N = N;
    tiling.H = H;
    tiling.K = K;
    tiling.M = M;
    tiling.intTileLen = intTileLen;
    tiling.xTileLen = xTileLen;
    tiling.maxExpert = maxExpert;
    tiling.ubSize = ubSize;

    // Create tiling tensor on device
    auto tilingTensor = at::empty({static_cast<int64_t>(sizeof(MoeInitRoutingTiling))},
                                  at::dtype(at::kByte).device(x.device()));
    {
        auto tiling_acc = tilingTensor.accessor<uint8_t, 1>();
        memcpy(tiling_acc.data(), &tiling, sizeof(MoeInitRoutingTiling));
    }

    // Cast to int64_t for EXEC_KERNEL_CMD (must be lvalues)
    int64_t blockDim = 1;
    const char *kernelName = nullptr;

    // Launch kernel based on dtype
    if (x.dtype() == at::kHalf) {
        kernelName = "moe_init_routing_fp16";
        EXEC_KERNEL_CMD(moe_init_routing_fp16, blockDim,
                        x, expert_flat, row_flat,
                        expanded_x, expanded_row_idx, expanded_expert_idx,
                        dst_to_src_ws, tilingTensor);
    } else if (x.dtype() == at::kFloat) {
        kernelName = "moe_init_routing_fp32";
        EXEC_KERNEL_CMD(moe_init_routing_fp32, blockDim,
                        x, expert_flat, row_flat,
                        expanded_x, expanded_row_idx, expanded_expert_idx,
                        dst_to_src_ws, tilingTensor);
    } else {
        // bfloat16
        kernelName = "moe_init_routing_bf16";
        EXEC_KERNEL_CMD(moe_init_routing_bf16, blockDim,
                        x, expert_flat, row_flat,
                        expanded_x, expanded_row_idx, expanded_expert_idx,
                        dst_to_src_ws, tilingTensor);
    }

    return expanded_x, expanded_row_idx, expanded_expert_idx;
}

}  // namespace ascend_kernel
