_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "moe_init_routing_ext*")

# Priority: whl import triggers TORCH_LIBRARY registration
try:
    import moe_init_routing_ext  # noqa: F401
except ImportError:
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """AscendC MoE routing initialization.

    Implements the same semantics as torch_npu.npu_moe_init_routing.
    All computation is done in the AscendC kernel via torch.ops.npu.moe_init_routing.
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor, row_idx: torch.Tensor,
                expert_idx: torch.Tensor, active_num: int):
        return torch.ops.npu.moe_init_routing(
            x, row_idx, expert_idx, active_num)
