static constexpr int32_t MAX_EXPERTS = 256;
static constexpr int32_t BUFFER_NUM = 1;

std::vector<at::Tensor> moe_init_routing(
    const at::Tensor &x,
    const at::Tensor &row_idx,
    const at::Tensor &expert_idx,
    int64_t active_num) {

    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(expert_idx.dim() == 2, "expert_idx must be 2D");
    TORCH_CHECK(row_idx.dim() == 2, "row_idx must be 2D");
    TORCH_CHECK(row_idx.sizes() == expert_idx.sizes(),
                "row_idx and expert_idx must have same shape");
    TORCH_CHECK(x.dtype() == at::kFloat || x.dtype() == at::kHalf ||
                x.dtype() == at::kBFloat16,
                "x dtype must be float32, float16, or bfloat16");
    TORCH_CHECK(expert_idx.dtype() == at::kInt, "expert_idx must be int32");
    TORCH_CHECK(row_idx.dtype() == at::kInt, "row_idx must be int32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int64_t N = x.size(0);
    int64_t H = x.size(1);
    int64_t K = expert_idx.size(1);
    int64_t M = N * K;

    // Flatten inputs
    auto expert_flat = expert_idx.contiguous().view(-1);
    auto row_flat = row_idx.contiguous().view(-1);

    // Allocate outputs
    auto expanded_x = at::empty({M, H}, x.options());
    auto expanded_row_idx = at::empty({M}, at::dtype(at::kInt).device(x.device()));
    auto expanded_expert_idx = at::empty({M}, at::dtype(at::kInt).device(x.device()));

    // Workspace for temporary dst_to_src
    auto dst_to_src_ws = at::empty({M}, at::dtype(at::kInt).device(x.device()));

    // Platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Compute tile lengths
    uint64_t ubOverhead = MAX_EXPERTS * sizeof(int32_t) * 3 + 4096;
    uint64_t usableUb = (ubSize > ubOverhead) ? (ubSize - ubOverhead) : (ubSize / 2);

    // intTileLen: how many int32 pairs we can process per tile
    int64_t intTileLen = static_cast<int64_t>(usableUb) /
                         (BUFFER_NUM * 2 * static_cast<int64_t>(sizeof(int32_t)));
    intTileLen = (intTileLen / 32) * 32;
    if (intTileLen < 64) intTileLen = 64;
    if (intTileLen > 2048) intTileLen = 2048;

    // xTileLen: how many x rows we can gather per tile (1 row at a time is simplest)
    int64_t xTileLen = 1;

    // Find max expert value
    int64_t maxExpert = 0;
    auto expert_acc = expert_flat.accessor<int32_t, 1>();
    for (int64_t i = 0; i < M; i++) {
        int32_t val = expert_acc[i];
        if (val > maxExpert) maxExpert = val;
    }
    if (maxExpert >= MAX_EXPERTS) {
        maxExpert = MAX_EXPERTS - 1;
    }

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.dtype() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.dtype() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All params as lvalues for EXEC_KERNEL_CMD
    int64_t blockDim = 1;

    EXEC_KERNEL_CMD(moe_init_routing, blockDim,
                    x, expert_flat, row_flat,
                    expanded_x, expanded_row_idx, expanded_expert_idx,
                    dst_to_src_ws,
                    N, H, K, M, intTileLen, xTileLen, maxExpert,
                    dtypeFlag);

    return {expanded_x, expanded_row_idx, expanded_expert_idx};
}

}  // namespace ascend_kernel
