{"content": "/*
 * Copyright (c) 2024. All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 *
 * MoeInitRouting AscendC Kernel
 *
 * Algorithm: Counting sort by expert ID, then gather x, then inverse mapping.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t MAX_EXPERTS = 256;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    LocalTensor<T> &dst, GlobalTensor<T> src, uint32_t count)
{
    DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    GlobalTensor<T> dst, LocalTensor<T> &src, uint32_t count)
{
    DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    DataCopyPad(dst, src, cp);
}

__aicore__ inline void CopyLocalInt32(
    LocalTensor<int32_t> &dst, LocalTensor<int32_t> &src, uint32_t count)
{
    DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
    DataCopy(dst, src, cp);
}

// =========================================================================
// MoeInitRouting Kernel
// =========================================================================

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ void Init(
        GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
        GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
        GM_ADDR expanded_expert_idx_gm, GM_ADDR dst_to_src_ws_gm,
        int64_t N, int64_t H, int64_t K, int64_t M,
        int64_t intTileLen, int64_t xTileLen, int64_t maxExpert) {

        N_ = static_cast<int32_t>(N);
        H_ = static_cast<int32_t>(H);
        K_ = static_cast<int32_t>(K);
        M_ = static_cast<int32_t>(M);
        intTileLen_ = static_cast<int32_t>(intTileLen);
        xTileLen_ = static_cast<int32_t>(xTileLen);
        maxExpert_ = static_cast<int32_t>(maxExpert) + 1;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x_gm), static_cast<uint64_t>(N_) * H_);
        expertGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expert_flat_gm), M_);
        rowGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(row_flat_gm), M_);
        expandedXGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(expanded_x_gm), static_cast<uint64_t>(M_) * H_);
        expandedRowGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_row_idx_gm), M_);
        expandedExpertGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_expert_idx_gm), M_);
        dstToSrcWsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(dst_to_src_ws_gm), M_);

        if ASCEND_IS_AIV {
            // TBuf (no BUFFER_NUM needed) for persistent histogram/offsets/cursors
            pipe.InitBuffer(histBuf_, (maxExpert_ + 1) * sizeof(int32_t));
            pipe.InitBuffer(offsetBuf_, (maxExpert_ + 1) * sizeof(int32_t));
            pipe.InitBuffer(cursorBuf_, (maxExpert_ + 1) * sizeof(int32_t));

            // TQue for streaming int32 data
            pipe.InitBuffer(inQueueExpert_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));
            pipe.InitBuffer(inQueueRow_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));

            // TQue for x data single-row copy
            pipe.InitBuffer(inQueueX_, BUFFER_NUM, H_ * sizeof(T));
            pipe.InitBuffer(outQueueX_, BUFFER_NUM, H_ * sizeof(T));
        }
    }

    __aicore__ void Process() {
        if ASCEND_IS_AIV {
            ComputeExpertHistogram();
            ComputePrefixSum();
            CountingSortScatter();
            GatherX();
            ComputeInverseMapping();
        }
    }

private:
    // Phase A: Count experts
    __aicore__ void ComputeExpertHistogram() {
        histLocal_ = histBuf_.Get<int32_t>();
        Duplicate<int32_t>(histLocal_, 0, maxExpert_ + 1);

        int32_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int32_t t = 0; t < numTiles; t++) {
            int32_t tileStart = t * intTileLen_;
            int32_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            expertLocal_ = inQueueExpert_.AllocTensor<int32_t>();
            LoadGmToUb(expertLocal_, expertGM_[tileStart], cur);
            inQueueExpert_.EnQue(expertLocal_);
            expertLocal_ = inQueueExpert_.DeQue<int32_t>();

            for (int32_t i = 0; i < cur; i++) {
                int32_t e = expertLocal_.GetValue(i);
                if (e >= 0 && e < maxExpert_) {
                    int32_t old = histLocal_.GetValue(e);
                    histLocal_.SetValue(e, old + 1);
                }
            }
            inQueueExpert_.FreeTensor(expertLocal_);
        }
        PipeBarrier<PIPE_ALL>();
    }

    // Phase A2: Prefix sum on histogram
    __aicore__ void ComputePrefixSum() {
        offsetLocal_ = offsetBuf_.Get<int32_t>();
        Duplicate<int32_t>(offsetLocal_, 0, maxExpert_ + 1);

        int32_t accum = 0;
        for (int32_t e = 0; e < maxExpert_; e++) {
            offsetLocal_.SetValue(e, accum);
            accum += histLocal_.GetValue(e);
        }
        offsetLocal_.SetValue(maxExpert_, accum);

        // Copy to cursor buffer for scatter
        cursorLocal_ = cursorBuf_.Get<int32_t>();
        CopyLocalInt32(cursorLocal_, offsetLocal_, maxExpert_ + 1);

        PipeBarrier<PIPE_ALL>();
    }

    // Phase B: Counting sort scatter
    __aicore__ void CountingSortScatter() {
        int32_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int32_t t = 0; t < numTiles; t++) {
            int32_t tileStart = t * intTileLen_;
            int32_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            expertLocal_ = inQueueExpert_.AllocTensor<int32_t>();
            LoadGmToUb(expertLocal_, expertGM_[tileStart], cur);
            inQueueExpert_.EnQue(expertLocal_);

            rowLocal_ = inQueueRow_.AllocTensor<int32_t>();
            LoadGmToUb(rowLocal_, rowGM_[tileStart], cur);
            inQueueRow_.EnQue(rowLocal_);

            expertLocal_ = inQueueExpert_.DeQue<int32_t>();
            rowLocal_ = inQueueRow_.DeQue<int32_t>();

            for (int32_t i = 0; i < cur; i++) {
                int32_t e = expertLocal_.GetValue(i);
                if (e >= 0 && e < maxExpert_) {
                    int32_t pos = cursorLocal_.GetValue(e);
                    int32_t row = rowLocal_.GetValue(i);

                    expandedExpertGM_.SetValue(pos, e);
                    dstToSrcWsGM_.SetValue(pos, row);

                    cursorLocal_.SetValue(e, pos + 1);
                }
            }

            inQueueExpert_.FreeTensor(expertLocal_);
            inQueueRow_.FreeTensor(rowLocal_);
        }
        PipeBarrier<PIPE_ALL>();
    }

    // Phase C: Gather x rows
    __aicore__ void GatherX() {
        int32_t numTiles = (M_ + xTileLen_ - 1) / xTileLen_;
        for (int32_t t = 0; t < numTiles; t++) {
            int32_t tileStart = t * xTileLen_;
            int32_t cur = (tileStart + xTileLen_ <= M_) ? xTileLen_ : (M_ - tileStart);

            for (int32_t i = 0; i < cur; i++) {
                int32_t pos = tileStart + i;
                int32_t row = dstToSrcWsGM_.GetValue(pos);
                int32_t xRow = row % N_;

                // Copy x[xRow, :] to expanded_x[pos, :]
                xInLocal_ = inQueueX_.AllocTensor<T>();
                LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(xRow) * H_], H_);
                inQueueX_.EnQue(xInLocal_);
                xInLocal_ = inQueueX_.DeQue<T>();

                StoreUbToGm(expandedXGM_[static_cast<uint64_t>(pos) * H_], xInLocal_, H_);

                inQueueX_.FreeTensor(xInLocal_);
            }
        }
        PipeBarrier<PIPE_ALL>();
    }

    // Phase D: Inverse mapping
    __aicore__ void ComputeInverseMapping() {
        int32_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int32_t t = 0; t < numTiles; t++) {
            int32_t tileStart = t * intTileLen_;
            int32_t cur = (tileStart + intTileLen_ <= M_) ? intTileLen_ : (M_ - tileStart);

            for (int32_t i = 0; i < cur; i++) {
                int32_t pos = tileStart + i;
                int32_t row = dstToSrcWsGM_.GetValue(pos);
                expandedRowGM_.SetValue(row, pos);
            }
        }
        PipeBarrier<PIPE_ALL>();
    }

    AscendC::TPipe pipe;
    int32_t N_, H_, K_, M_;
    int32_t intTileLen_, xTileLen_;
    int32_t maxExpert_;

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<int32_t> expertGM_;
    AscendC::GlobalTensor<int32_t> rowGM_;
    AscendC::GlobalTensor<T> expandedXGM_;
    AscendC::GlobalTensor<int32_t> expandedRowGM_;
    AscendC::GlobalTensor<int32_t> expandedExpertGM_;
    AscendC::GlobalTensor<int32_t> dstToSrcWsGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cursorBuf_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueExpert_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueRow_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueX_;

    AscendC::LocalTensor<int32_t> histLocal_;
    AscendC::LocalTensor<int32_t> offsetLocal_;
    AscendC::LocalTensor<int32_t> cursorLocal_;
    AscendC::LocalTensor<int32_t> expertLocal_;
    AscendC::LocalTensor<int32_t> rowLocal_;
    AscendC::LocalTensor<T> xInLocal_;
};

// =========================================================================
// dtype dispatch + kernel entry
// =========================================================================

template <template <typename> class Kernel>
__aicore__ inline void DispatchMoeInitRouting(
    GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
    GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
    GM_ADDR expanded_expert_idx_gm, GM_ADDR dst_to_src_ws_gm,
    int64_t N, int64_t H, int64_t K, int64_t M,
    int64_t intTileLen, int64_t xTileLen, int64_t maxExpert,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,
                    expanded_row_idx_gm, expanded_expert_idx_gm,
                    dst_to_src_ws_gm, N, H, K, M, intTileLen, xTileLen, maxExpert);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,
                    expanded_row_idx_gm, expanded_expert_idx_gm,
                    dst_to_src_ws_gm, N, H, K, M, intTileLen, xTileLen, maxExpert);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,
                    expanded_row_idx_gm, expanded_expert_idx_gm,
                    dst_to_src_ws_gm, N, H, K, M, intTileLen, xTileLen, maxExpert);
        kernel.Process();
    }
}

extern "C" __global__ __aicore__ void moe_init_routing(
    GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
    GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
    GM_ADDR expanded_expert_idx_gm, GM_ADDR dst_to_src_ws_gm,
    int64_t N, int64_t H, int64_t K, int64_t M,
    int64_t intTileLen, int64_t xTileLen, int64_t maxExpert,
    int64_t dtypeFlag)
{
    DispatchMoeInitRouting<KernelMoeInitRouting>(
        x_gm, expert_flat_gm, row_flat_gm,
        expanded_x_gm, expanded_row_idx_gm,
        expanded_expert_idx_gm, dst_to_src_ws_gm,
        N, H, K, M, intTileLen, xTileLen, maxExpert, dtypeFlag);
}
