            inQueueRow_.EnQue(rowLocal_);

            expertLocal_ = inQueueExpert_.DeQue<int32_t>();
            rowLocal_ = inQueueRow_.DeQue<int32_t>();

            for (int32_t i = 0; i < cur; i++) {
                int32_t e = expertLocal_.GetValue(i);
                if (e < 0 || e >= maxExpert_) continue;

                int32_t pos = cursorLocal_.GetValue(e);
                int32_t row = rowLocal_.GetValue(i);

                GmWriteInt32(expandedExpertGM_[pos], e);
                GmWriteInt32(dstToSrcWsGM_[pos], row);

                cursorLocal_.SetValue(e, pos + 1);
            }

            inQueueExpert_.FreeTensor(expertLocal_);
            inQueueRow_.FreeTensor(rowLocal_);
        }
        PipeBarrier<PIPE_ALL>();
    }

    // ----------------------------------------------------------------
    // Phase C+D: Gather x + Inverse mapping
    // ----------------------------------------------------------------
    __aicore__ void GatherXAndInverseMap() {
        for (int32_t pos = 0; pos < M_; pos++) {
            int32_t row = GmReadInt32(dstToSrcWsGM_[pos]);
            int32_t xRow = row % N_;

            xInLocal_ = inQueueX_.AllocTensor<T>();
            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(xRow) * H_], H_);
            inQueueX_.EnQue(xInLocal_);
            xInLocal_ = inQueueX_.DeQue<T>();
            StoreUbToGm(expandedXGM_[static_cast<uint64_t>(pos) * H_], xInLocal_, H_);
            inQueueX_.FreeTensor(xInLocal_);

            GmWriteInt32(expandedRowGM_[row], pos);
        }
        PipeBarrier<PIPE_ALL>();
    }

    AscendC::TPipe pipe;
    int32_t N_, H_, M_;
    int32_t intTileLen_;
    int32_t maxExpert_;

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<int32_t> expertGM_, rowGM_, expandedRowGM_;
    AscendC::GlobalTensor<int32_t> expandedExpertGM_, dstToSrcWsGM_;
    AscendC::GlobalTensor<T> expandedXGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_, offsetBuf_, cursorBuf_, stagingBuf_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueExpert_, inQueueRow_, inQueueX_;

    AscendC::LocalTensor<int32_t> histLocal_, offsetLocal_, cursorLocal_;
    AscendC::LocalTensor<int32_t> expertLocal_, rowLocal_;
    AscendC::LocalTensor<T> xInLocal_;
};

template <template <typename> class Kernel>
__aicore__ inline void DispatchMoeInitRouting(
