 * SPDX-License-Identifier: BSD-3-Clause
 *
 * MoeInitRouting AscendC Kernel — Counting sort by expert ID
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t MAX_EXPERTS = 256;

template <typename T>
__aicore__ inline void LoadGmToUbPad(
    LocalTensor<T> &dst, GlobalTensor<T> src, uint32_t count)
{
    DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbToGmPad(
    GlobalTensor<T> dst, LocalTensor<T> &src, uint32_t count)
{
    DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    DataCopyPad(dst, src, cp);
}

template <typename T>
class KernelMoeInitRouting {
public:
    __aicore__ void Init(
        GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
        GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
        GM_ADDR expanded_expert_idx_gm, GM_ADDR dst_to_src_ws_gm,
        int64_t N, int64_t H, int64_t K, int64_t M,
        int64_t intTileLen, int64_t maxExpert) {

        N_ = static_cast<int32_t>(N);
        H_ = static_cast<int32_t>(H);
        M_ = static_cast<int32_t>(M);
        intTileLen_ = static_cast<int32_t>(intTileLen);
        maxExpert_ = static_cast<int32_t>(maxExpert) + 1;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x_gm), static_cast<uint64_t>(N_) * H_);
        expertGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expert_flat_gm), M_);
        rowGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(row_flat_gm), M_);
        expandedXGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(expanded_x_gm), static_cast<uint64_t>(M_) * H_);
        expandedRowGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_row_idx_gm), M_);
        expandedExpertGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(expanded_expert_idx_gm), M_);
        dstToSrcWsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(dst_to_src_ws_gm), M_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(histBuf_, (maxExpert_ + 1) * sizeof(int32_t));
            pipe.InitBuffer(offsetBuf_, (maxExpert_ + 1) * sizeof(int32_t));
            pipe.InitBuffer(cursorBuf_, (maxExpert_ + 1) * sizeof(int32_t));

            pipe.InitBuffer(inExpert_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));
            pipe.InitBuffer(inRow_, BUFFER_NUM, intTileLen_ * sizeof(int32_t));

            // TBuf for x staging (not TQue — used for both read and write with PipeBarrier)
            pipe.InitBuffer(xBuf_, H_ * sizeof(T));

            // Staging buffer for small GM writes (32B = 8 int32)
            pipe.InitBuffer(stagingBuf_, 8 * sizeof(int32_t));
        }
    }

    __aicore__ void Process() {
        if ASCEND_IS_AIV {
            ComputeHistogram();
            ComputePrefixSum();
            CountingSortScatter();
            GatherAndInverseMap();
        }
    }

private:
    // ================================================================
    // Small GM write/read via UB staging + DataCopyPad (safe)
    // ================================================================
    __aicore__ void WriteInt32(GlobalTensor<int32_t> dst, int32_t val) {
        LocalTensor<int32_t> s = stagingBuf_.Get<int32_t>();
        s.SetValue(0, val);
        uint32_t bs = static_cast<uint32_t>(4 * sizeof(int32_t));
        DataCopyExtParams cp{1, bs, 0, 0, 0};
        DataCopyPad(dst, s, cp);
        PipeBarrier<PIPE_MTE3>();
    }

    __aicore__ int32_t ReadInt32(GlobalTensor<int32_t> src) {
        LocalTensor<int32_t> s = stagingBuf_.Get<int32_t>();
        uint32_t bs = static_cast<uint32_t>(4 * sizeof(int32_t));
        DataCopyExtParams cp{1, bs, 0, 0, 0};
        DataCopyPadExtParams<int32_t> pp{true, 0, 0, 0};
        DataCopyPad(s, src, cp, pp);
        PipeBarrier<PIPE_MTE3>();
        return s.GetValue(0);
    }

    // ================================================================
    // Phase A: Histogram
    // ================================================================
    __aicore__ void ComputeHistogram() {
        hist_ = histBuf_.Get<int32_t>();
        Duplicate<int32_t>(hist_, 0, maxExpert_ + 1);

        int32_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int32_t t = 0; t < numTiles; t++) {
            int32_t start = t * intTileLen_;
            int32_t cur = (start + intTileLen_ <= M_) ? intTileLen_ : (M_ - start);

            expertIn_ = inExpert_.AllocTensor<int32_t>();
            LoadGmToUbPad(expertIn_, expertGM_[start], cur);
            inExpert_.EnQue(expertIn_);
            expertIn_ = inExpert_.DeQue<int32_t>();

            for (int32_t i = 0; i < cur; i++) {
                int32_t e = expertIn_.GetValue(i);
                if (e >= 0 && e < maxExpert_) {
                    hist_.SetValue(e, hist_.GetValue(e) + 1);
                }
            }
            inExpert_.FreeTensor(expertIn_);
        }
        PipeBarrier<PIPE_ALL>();
    }

    // ================================================================
    // Phase A2: Prefix sum
    // ================================================================
    __aicore__ void ComputePrefixSum() {
        offset_ = offsetBuf_.Get<int32_t>();
        cursor_ = cursorBuf_.Get<int32_t>();

        int32_t accum = 0;
        for (int32_t e = 0; e < maxExpert_; e++) {
            offset_.SetValue(e, accum);
            cursor_.SetValue(e, accum);
            accum += hist_.GetValue(e);
        }
        offset_.SetValue(maxExpert_, accum);
        PipeBarrier<PIPE_ALL>();
    }

    // ================================================================
    // Phase B: Counting sort scatter
    // ================================================================
    __aicore__ void CountingSortScatter() {
        int32_t numTiles = (M_ + intTileLen_ - 1) / intTileLen_;
        for (int32_t t = 0; t < numTiles; t++) {
            int32_t start = t * intTileLen_;
            int32_t cur = (start + intTileLen_ <= M_) ? intTileLen_ : (M_ - start);

            expertIn_ = inExpert_.AllocTensor<int32_t>();
            LoadGmToUbPad(expertIn_, expertGM_[start], cur);
            inExpert_.EnQue(expertIn_);

            rowIn_ = inRow_.AllocTensor<int32_t>();
            LoadGmToUbPad(rowIn_, rowGM_[start], cur);
            inRow_.EnQue(rowIn_);

            expertIn_ = inExpert_.DeQue<int32_t>();
            rowIn_ = inRow_.DeQue<int32_t>();

            for (int32_t i = 0; i < cur; i++) {
                int32_t e = expertIn_.GetValue(i);
                if (e < 0 || e >= maxExpert_) continue;

                int32_t pos = cursor_.GetValue(e);
                int32_t row = rowIn_.GetValue(i);

                WriteInt32(expandedExpertGM_[pos], e);
                WriteInt32(dstToSrcWsGM_[pos], row);

                cursor_.SetValue(e, pos + 1);
            }

            inExpert_.FreeTensor(expertIn_);
            inRow_.FreeTensor(rowIn_);
        }
        PipeBarrier<PIPE_ALL>();
    }

    // ================================================================
    // Phase C+D: Gather x rows + Inverse mapping
    // ================================================================
    __aicore__ void GatherAndInverseMap() {
        for (int32_t pos = 0; pos < M_; pos++) {
            int32_t row = ReadInt32(dstToSrcWsGM_[pos]);
            int32_t xRow = row % N_;

            // Read x[xRow, :] via TBuf + PipeBarrier (correct pipe discipline)
            xLocal_ = xBuf_.Get<T>();
            DataCopyExtParams cp{
                1,
                static_cast<uint32_t>(H_) * static_cast<uint32_t>(sizeof(T)),
                0, 0, 0
            };
            DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
            DataCopyPad(xLocal_, xGM_[static_cast<uint64_t>(xRow) * H_], cp, pp);
            PipeBarrier<PIPE_MTE2>();

            // Write to expanded_x[pos, :] via TBuf (explicit pipe discipline)
            DataCopyPad(expandedXGM_[static_cast<uint64_t>(pos) * H_], xLocal_, cp);
            PipeBarrier<PIPE_MTE3>();

            // Inverse mapping
            WriteInt32(expandedRowGM_[row], pos);
        }
        PipeBarrier<PIPE_ALL>();
    }

    AscendC::TPipe pipe;
    int32_t N_, H_, M_;
    int32_t intTileLen_;
    int32_t maxExpert_;

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<int32_t> expertGM_, rowGM_, expandedRowGM_;
    AscendC::GlobalTensor<int32_t> expandedExpertGM_, dstToSrcWsGM_;
    AscendC::GlobalTensor<T> expandedXGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_, offsetBuf_, cursorBuf_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inExpert_, inRow_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf_, stagingBuf_;

    AscendC::LocalTensor<int32_t> hist_, offset_, cursor_;
    AscendC::LocalTensor<int32_t> expertIn_, rowIn_;
    AscendC::LocalTensor<T> xLocal_;
};

template <template <typename> class Kernel>
__aicore__ inline void DispatchMoeInitRouting(
    GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
    GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
    GM_ADDR expanded_expert_idx_gm, GM_ADDR dst_to_src_ws_gm,
    int64_t N, int64_t H, int64_t K, int64_t M,
    int64_t intTileLen, int64_t maxExpert, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,
                    expanded_row_idx_gm, expanded_expert_idx_gm,
                    dst_to_src_ws_gm, N, H, K, M, intTileLen, maxExpert);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,
                    expanded_row_idx_gm, expanded_expert_idx_gm,
                    dst_to_src_ws_gm, N, H, K, M, intTileLen, maxExpert);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x_gm, expert_flat_gm, row_flat_gm, expanded_x_gm,
                    expanded_row_idx_gm, expanded_expert_idx_gm,
                    dst_to_src_ws_gm, N, H, K, M, intTileLen, maxExpert);
        kernel.Process();
    }
}

extern "C" __global__ __aicore__ void moe_init_routing(
    GM_ADDR x_gm, GM_ADDR expert_flat_gm, GM_ADDR row_flat_gm,
    GM_ADDR expanded_x_gm, GM_ADDR expanded_row_idx_gm,
    GM_ADDR expanded_expert_idx_gm, GM_ADDR dst_to_src_ws_gm,
    int64_t N, int64_t H, int64_t K, int64_t M,
    int64_t intTileLen, int64_t maxExpert, int64_t dtypeFlag)
{
    DispatchMoeInitRouting<KernelMoeInitRouting>(
        x_gm, expert_flat_gm, row_flat_gm,
        expanded_x_gm, expanded_row_idx_gm,
        expanded_expert_idx_gm, dst_to_src_ws_gm,
        N, H, K, M, intTileLen, maxExpert, dtypeFlag);
}
