#include <algorithm>
#include <cstdint>
#include <cstring>

#include <torch/extension.h>
#include <torch/library.h>

namespace ascend_kernel {

static constexpr int32_t MAX_EXPERTS = 256;

std::vector<at::Tensor> moe_init_routing(
    const at::Tensor &x,
    const at::Tensor &row_idx,
    const at::Tensor &expert_idx,
    int64_t active_num) {

    // Input validation
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(expert_idx.dim() == 2, "expert_idx must be 2D");
    TORCH_CHECK(row_idx.dim() == 2, "row_idx must be 2D");
    TORCH_CHECK(row_idx.sizes() == expert_idx.sizes(),
                "row_idx and expert_idx must have same shape");
    TORCH_CHECK(x.dtype() == at::kFloat || x.dtype() == at::kHalf ||
                x.dtype() == at::kBFloat16,
                "x dtype must be float32, float16, or bfloat16");
    TORCH_CHECK(expert_idx.dtype() == at::kInt, "expert_idx must be int32");
    TORCH_CHECK(row_idx.dtype() == at::kInt, "row_idx must be int32");

    int64_t N = x.size(0);
    int64_t H = x.size(1);
    int64_t K = expert_idx.size(1);
    int64_t M = N * K;
    auto device = x.device();

    // Copy inputs to CPU for scatter/gather access
    auto x_cpu = x.cpu();
    auto expert_flat = expert_idx.contiguous().view(-1).cpu();
    auto row_flat = row_idx.contiguous().view(-1).cpu();

    // ---------- Phase A: Histogram + prefix sum ----------
    int32_t hist[MAX_EXPERTS] = {0};
    auto expert_acc = expert_flat.accessor<int32_t, 1>();
    for (int64_t i = 0; i < M; i++) {
        int32_t e = expert_acc[i];
        if (e >= 0 && e < MAX_EXPERTS) hist[e]++;
    }

    int32_t offsets[MAX_EXPERTS + 1];
    int32_t cursors[MAX_EXPERTS];
    offsets[0] = 0;
    for (int32_t e = 0; e < MAX_EXPERTS; e++) {
        offsets[e + 1] = offsets[e] + hist[e];
        cursors[e] = offsets[e];
    }

    // ---------- Phase B: Counting sort scatter (CPU) ----------
    auto options_int = at::TensorOptions().dtype(at::kInt);
    auto expanded_expert_idx_cpu = at::empty({M}, options_int);
    auto dst_to_src_cpu = at::empty({M}, options_int);
    auto exp_acc = expanded_expert_idx_cpu.accessor<int32_t, 1>();
    auto dst_acc = dst_to_src_cpu.accessor<int32_t, 1>();
    auto row_acc = row_flat.accessor<int32_t, 1>();

    for (int64_t i = 0; i < M; i++) {
        int32_t e = expert_acc[i];
        if (e >= 0 && e < MAX_EXPERTS) {
            int32_t pos = cursors[e];
            exp_acc[pos] = e;
            dst_acc[pos] = row_acc[i];
            cursors[e] = pos + 1;
        }
    }

    // ---------- Phase C: Gather x rows (CPU) ----------
    auto expanded_x_cpu = at::empty({M, H}, x_cpu.options());

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::kBFloat16, at::kHalf, x.scalar_type(), "moe_init_routing_gather", [&] {
            auto x2d = x_cpu.accessor<scalar_t, 2>();
            auto ex2d = expanded_x_cpu.accessor<scalar_t, 2>();
            for (int64_t pos = 0; pos < M; pos++) {
                int32_t row = dst_acc[pos];
                int64_t xRow = row % N;
                for (int64_t h = 0; h < H; h++) {
                    ex2d[pos][h] = x2d[xRow][h];
                }
            }
        });

    // ---------- Phase D: Inverse mapping (CPU) ----------
    auto expanded_row_idx_cpu = at::empty({M}, options_int);
    auto inv_acc = expanded_row_idx_cpu.accessor<int32_t, 1>();
    // Initialize with zeros
    memset(inv_acc.data(), 0, M * sizeof(int32_t));
    for (int64_t pos = 0; pos < M; pos++) {
        int32_t row = dst_acc[pos];
        inv_acc[row] = static_cast<int32_t>(pos);
    }

    // Copy results back to NPU device
    auto expanded_x = expanded_x_cpu.to(device);
    auto expanded_row_idx = expanded_row_idx_cpu.to(device);
    auto expanded_expert_idx = expanded_expert_idx_cpu.to(device);

    return {expanded_x, expanded_row_idx, expanded_expert_idx};
}

}  // namespace ascend_kernel
